CREATE TABLE "JobEvaluationCriterion" ("id" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "title" TEXT NOT NULL, "weight" INTEGER NOT NULL, "status" "PositionStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "JobEvaluationCriterion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "JobEvaluation" ("id" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "jobProfileId" TEXT NOT NULL, "score" INTEGER NOT NULL, "status" "PositionStatus" NOT NULL DEFAULT 'ACTIVE', "evaluatorUserId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "JobEvaluation_pkey" PRIMARY KEY ("id"));
